import { ConfigProvider } from 'antd';
import { ProTable } from '@ant-design/pro-components';

export default function GeneratedPage() {
  return (
    <ConfigProvider theme={{ token: { colorPrimary: '#1677ff', borderRadius: 8 } }}>
      <ProTable
        headerTitle={"用户数据"}
        search={true}
        options={true}
        rowKey={"id"}
        pagination={{ "pageSize": 2, "showSizeChanger": true }}
        columns={[{"title":"用户名称","dataIndex":"name"},{"title":"邮箱","dataIndex":"email"}]}
        dataSource={[{"id":"1","name":"张三","email":"a@b.c"},{"id":"2","name":"李四","email":"d@e.f"},{"id":"3","name":"王五","email":"g@h.i"}]}
      />
    </ConfigProvider>
  );
}
